META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–10: ಅರ್ಜುನ ಯುದ್ಧ ಮಾಡಲು ನಿರಾಕರಿಸಿ ಶ್ರೀಕೃಷ್ಣನ ಶಿಷ್ಯನಾಗಿ ಶರಣು ಬರುತ್ತಾನೆ; 11–30: ಆತ್ಮ ಹುಟ್ಟುವುದಿಲ್ಲ, ಸಾಯುವುದಿಲ್ಲ; 31–38: ಕ್ಷತ್ರಿಯನಾಗಿ ಅರ್ಜುನನ ಕರ್ತವ್ಯ; 39–53: ಕರ್ಮಯೋಗ: ಫಲದ ಆಸಕ್ತಿಯಿಲ್ಲದೆ ಕರ್ಮ ಮಾಡು; 54–72: ಸ್ಥಿತಪ್ರಜ್ಞನ, ಅಂದರೆ ಸ್ಥಿರ ಬುದ್ಧಿಯುಳ್ಳವನ ಲಕ್ಷಣಗಳು.',
)
T = {
1: 'ಸಂಜಯ ಹೇಳಿದನು: ಕರುಣೆಯಿಂದ ತುಂಬಿ, ಕಣ್ಣೀರು ತುಂಬಿದ ಕಳವಳದ ಕಣ್ಣುಗಳೊಂದಿಗೆ ದುಃಖಿಸುತ್ತಿದ್ದ ಅರ್ಜುನನಿಗೆ ಮಧುಸೂದನ ಹೀಗೆ ಹೇಳಿದನು.',
2: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಅರ್ಜುನ, ಈ ಸಂಕಟದ ಸಮಯದಲ್ಲಿ ಈ ದೌರ್ಬಲ್ಯ ನಿನಗೆ ಎಲ್ಲಿಂದ ಬಂತು? ಇದು ಶ್ರೇಷ್ಠರಿಗೆ ತಕ್ಕದ್ದಲ್ಲ, ಸ್ವರ್ಗಕ್ಕೆ ಕೊಂಡೊಯ್ಯುವುದಿಲ್ಲ, ಅಪಕೀರ್ತಿಯನ್ನು ತರುತ್ತದೆ.',
3: 'ಹೇ ಪಾರ್ಥ, ಹೇಡಿತನಕ್ಕೆ ಒಳಗಾಗಬೇಡ, ಇದು ನಿನಗೆ ಶೋಭಿಸುವುದಿಲ್ಲ. ಹೇ ಪರಂತಪ, ಹೃದಯದ ಈ ಕ್ಷುದ್ರ ದೌರ್ಬಲ್ಯವನ್ನು ಬಿಟ್ಟು ಎದ್ದೇಳು.',
4: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಮಧುಸೂದನ, ಪೂಜೆಗೆ ಅರ್ಹರಾದ ಭೀಷ್ಮ ಮತ್ತು ದ್ರೋಣರ ವಿರುದ್ಧ ನಾನು ಯುದ್ಧದಲ್ಲಿ ಬಾಣಗಳಿಂದ ಹೇಗೆ ಹೋರಾಡಲಿ?',
5: 'ಮಹಾನುಭಾವರಾದ ಗುರುಗಳನ್ನು ಕೊಲ್ಲುವುದಕ್ಕಿಂತ ಈ ಲೋಕದಲ್ಲಿ ಭಿಕ್ಷೆ ಬೇಡಿ ತಿನ್ನುವುದೇ ಮೇಲು. ಅವರನ್ನು ಕೊಂದರೆ, ನಾನು ಇಲ್ಲಿ ಅನುಭವಿಸುವ ಸಂಪತ್ತು ಮತ್ತು ಸುಖಗಳು ರಕ್ತದಿಂದ ಕಲೆಯಾಗಿರುತ್ತವೆ.',
6: 'ನಾವು ಅವರನ್ನು ಗೆಲ್ಲುವುದು ಒಳ್ಳೆಯದೋ, ಅವರು ನಮ್ಮನ್ನು ಗೆಲ್ಲುವುದು ಒಳ್ಳೆಯದೋ ಎಂದು ನಮಗೆ ತಿಳಿಯದು. ಯಾರನ್ನು ಕೊಂದು ನಾವು ಬದುಕಲೂ ಬಯಸುವುದಿಲ್ಲವೋ, ಆ ಧೃತರಾಷ್ಟ್ರನ ಮಕ್ಕಳೇ ಎದುರು ನಿಂತಿದ್ದಾರೆ.',
7: 'ಕರುಣೆಯ ದೌರ್ಬಲ್ಯದಿಂದ ನನ್ನ ಸ್ವಭಾವ ಕುಸಿದಿದೆ, ಧರ್ಮದ ಬಗ್ಗೆ ನನ್ನ ಮನಸ್ಸು ಗೊಂದಲದಲ್ಲಿದೆ. ನನಗೆ ಯಾವುದು ನಿಜವಾಗಿ ಒಳ್ಳೆಯದೋ ಅದನ್ನು ನಿಶ್ಚಯವಾಗಿ ಹೇಳಿ. ನಾನು ನಿಮ್ಮ ಶಿಷ್ಯ, ನಿಮ್ಮ ಶರಣು ಬಂದಿದ್ದೇನೆ, ನನಗೆ ಉಪದೇಶಿಸಿ.',
8: 'ಭೂಮಿಯ ಮೇಲೆ ಶತ್ರುವಿಲ್ಲದ ಸಮೃದ್ಧ ರಾಜ್ಯ ಸಿಕ್ಕರೂ, ದೇವತೆಗಳ ಮೇಲೆ ಆಧಿಪತ್ಯ ಸಿಕ್ಕರೂ, ನನ್ನ ಇಂದ್ರಿಯಗಳನ್ನು ಒಣಗಿಸುತ್ತಿರುವ ಈ ದುಃಖವನ್ನು ಯಾವುದು ದೂರಮಾಡುತ್ತದೆಂದು ನನಗೆ ಕಾಣುತ್ತಿಲ್ಲ.',
9: 'ಸಂಜಯ ಹೇಳಿದನು: ಹೇ ರಾಜನೇ, ಗುಡಾಕೇಶ (ಅರ್ಜುನ) ಹೃಷೀಕೇಶನಿಗೆ ಹೀಗೆ ಹೇಳಿ, "ಗೋವಿಂದ, ನಾನು ಯುದ್ಧ ಮಾಡುವುದಿಲ್ಲ" ಎಂದು ಹೇಳಿ ಮೌನವಾದನು.',
10: 'ಹೇ ಭಾರತ (ಧೃತರಾಷ್ಟ್ರ), ಎರಡೂ ಸೇನೆಗಳ ನಡುವೆ ದುಃಖಿಸುತ್ತಿದ್ದ ಅವನಿಗೆ ಹೃಷೀಕೇಶ ಮುಗುಳ್ನಗುತ್ತಾ ಈ ಮಾತುಗಳನ್ನು ಹೇಳಿದನು.',
11: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ದುಃಖಿಸಬಾರದವರಿಗಾಗಿ ನೀನು ದುಃಖಿಸುತ್ತಿದ್ದೀಯ, ಆದರೂ ಜ್ಞಾನಿಗಳಂತೆ ಮಾತನಾಡುತ್ತೀಯ. ಜ್ಞಾನಿಗಳು ಸತ್ತವರಿಗಾಗಲಿ ಬದುಕಿರುವವರಿಗಾಗಲಿ ದುಃಖಿಸುವುದಿಲ್ಲ.',
12: 'ನಾನಾಗಲಿ, ನೀನಾಗಲಿ, ಈ ರಾಜರಾಗಲಿ ಇಲ್ಲದಿದ್ದ ಸಮಯ ಎಂದೂ ಇರಲಿಲ್ಲ; ಮುಂದೆಯೂ ನಾವೆಲ್ಲರೂ ಇಲ್ಲದಿರುವ ಸಮಯ ಬರುವುದಿಲ್ಲ.',
13: 'ದೇಹಧಾರಿಗೆ ಈ ದೇಹದಲ್ಲಿ ಬಾಲ್ಯ, ಯೌವನ ಮತ್ತು ಮುಪ್ಪು ಬರುವಂತೆಯೇ ಇನ್ನೊಂದು ದೇಹವೂ ಸಿಗುತ್ತದೆ. ಧೀರನು ಇದರಿಂದ ಗೊಂದಲಗೊಳ್ಳುವುದಿಲ್ಲ.',
14: 'ಹೇ ಕೌಂತೇಯ, ಇಂದ್ರಿಯಗಳು ವಿಷಯಗಳನ್ನು ಸ್ಪರ್ಶಿಸಿದಾಗ ಚಳಿ-ಸೆಕೆ, ಸುಖ-ದುಃಖ ಉಂಟಾಗುತ್ತವೆ. ಅವು ಬಂದು ಹೋಗುತ್ತವೆ, ಶಾಶ್ವತವಲ್ಲ. ಹೇ ಭಾರತ, ಅವುಗಳನ್ನು ಸಹಿಸಿಕೋ.',
15: 'ಹೇ ಪುರುಷಶ್ರೇಷ್ಠ, ಇವುಗಳಿಂದ ಕಳವಳಗೊಳ್ಳದ, ಸುಖ-ದುಃಖಗಳಲ್ಲಿ ಸಮನಾಗಿರುವ ಧೀರನೇ ಅಮೃತತ್ವಕ್ಕೆ ಅರ್ಹನಾಗುತ್ತಾನೆ.',
16: 'ಅಸತ್ತಿಗೆ ಅಸ್ತಿತ್ವವಿಲ್ಲ, ಸತ್ತಿಗೆ ಅಭಾವವಿಲ್ಲ. ತತ್ತ್ವವನ್ನು ಕಂಡವರು ಇವೆರಡರ ಸತ್ಯವನ್ನೂ ಕಂಡಿದ್ದಾರೆ.',
17: 'ಯಾವುದರಿಂದ ಈ ಎಲ್ಲವೂ ವ್ಯಾಪಿಸಿದೆಯೋ ಅದು ಅವಿನಾಶಿ ಎಂದು ತಿಳಿ. ಆ ಅವ್ಯಯವನ್ನು ಯಾರೂ ನಾಶಮಾಡಲಾರರು.',
18: 'ನಿತ್ಯನೂ, ಅವಿನಾಶಿಯೂ, ಅಳೆಯಲಾಗದವನೂ ಆದ ದೇಹಧಾರಿಯ ಈ ದೇಹಗಳು ನಾಶವಾಗುವಂಥವು ಎಂದು ಹೇಳಲಾಗಿದೆ. ಆದ್ದರಿಂದ ಹೇ ಭಾರತ, ಯುದ್ಧ ಮಾಡು.',
19: 'ಇವನನ್ನು ಕೊಲ್ಲುವವನೆಂದು ತಿಳಿಯುವವನೂ, ಕೊಲ್ಲಲ್ಪಟ್ಟವನೆಂದು ತಿಳಿಯುವವನೂ ಇಬ್ಬರೂ ತಿಳಿಯರು. ಇವನು ಕೊಲ್ಲುವುದೂ ಇಲ್ಲ, ಕೊಲ್ಲಲ್ಪಡುವುದೂ ಇಲ್ಲ.',
21: 'ಹೇ ಪಾರ್ಥ, ಇವನನ್ನು ಅವಿನಾಶಿ, ನಿತ್ಯ, ಜನ್ಮರಹಿತ ಮತ್ತು ಅವ್ಯಯ ಎಂದು ತಿಳಿದವನು ಯಾರನ್ನಾದರೂ ಹೇಗೆ ಕೊಲ್ಲಿಸುತ್ತಾನೆ, ಯಾರನ್ನು ಹೇಗೆ ಕೊಲ್ಲುತ್ತಾನೆ?',
23: 'ಇವನನ್ನು ಶಸ್ತ್ರಗಳು ಕತ್ತರಿಸಲಾರವು, ಬೆಂಕಿ ಸುಡಲಾರದು, ನೀರು ನೆನೆಸಲಾರದು, ಗಾಳಿ ಒಣಗಿಸಲಾರದು.',
24: 'ಇವನು ಕತ್ತರಿಸಲಾಗದವನು, ಸುಡಲಾಗದವನು, ನೆನೆಸಲಾಗದವನು, ಒಣಗಿಸಲಾಗದವನು. ಇವನು ನಿತ್ಯ, ಸರ್ವವ್ಯಾಪಿ, ಸ್ಥಿರ, ಅಚಲ ಮತ್ತು ಸನಾತನ.',
25: 'ಇವನನ್ನು ಅವ್ಯಕ್ತ, ಅಚಿಂತ್ಯ ಮತ್ತು ವಿಕಾರರಹಿತ ಎನ್ನುತ್ತಾರೆ. ಆದ್ದರಿಂದ ಇವನನ್ನು ಹೀಗೆ ತಿಳಿದು ನೀನು ದುಃಖಿಸಬಾರದು.',
26: 'ಹೇ ಮಹಾಬಾಹು, ಇವನು ನಿರಂತರವಾಗಿ ಹುಟ್ಟುತ್ತಾನೆ, ನಿರಂತರವಾಗಿ ಸಾಯುತ್ತಾನೆ ಎಂದು ನೀನು ಭಾವಿಸಿದರೂ, ನೀನು ಹೀಗೆ ದುಃಖಿಸಬಾರದು.',
27: 'ಹುಟ್ಟಿದವನಿಗೆ ಸಾವು ನಿಶ್ಚಿತ, ಸತ್ತವನಿಗೆ ಹುಟ್ಟು ನಿಶ್ಚಿತ. ಆದ್ದರಿಂದ ತಪ್ಪಿಸಲಾಗದ ವಿಷಯಕ್ಕಾಗಿ ನೀನು ದುಃಖಿಸಬಾರದು.',
28: 'ಹೇ ಭಾರತ, ಜೀವಿಗಳು ಆದಿಯಲ್ಲಿ ಅವ್ಯಕ್ತ, ಮಧ್ಯದಲ್ಲಿ ವ್ಯಕ್ತ, ಕೊನೆಯಲ್ಲಿ ಮತ್ತೆ ಅವ್ಯಕ್ತ. ಇದರಲ್ಲಿ ದುಃಖಿಸಲು ಏನಿದೆ?',
29: 'ಯಾರೋ ಒಬ್ಬರು ಇವನನ್ನು ಆಶ್ಚರ್ಯದಂತೆ ನೋಡುತ್ತಾರೆ, ಇನ್ನೊಬ್ಬರು ಆಶ್ಚರ್ಯದಂತೆ ವರ್ಣಿಸುತ್ತಾರೆ, ಮತ್ತೊಬ್ಬರು ಆಶ್ಚರ್ಯದಂತೆ ಕೇಳುತ್ತಾರೆ; ಕೇಳಿದರೂ ಯಾರೂ ಇವನನ್ನು ತಿಳಿಯರು.',
30: 'ಹೇ ಭಾರತ, ಎಲ್ಲರ ದೇಹದಲ್ಲಿರುವ ಈ ದೇಹಧಾರಿ ಎಂದಿಗೂ ಕೊಲ್ಲಲಾಗದವನು. ಆದ್ದರಿಂದ ಯಾವ ಜೀವಿಗಾಗಿಯೂ ನೀನು ದುಃಖಿಸಬಾರದು.',
31: 'ನಿನ್ನ ಸ್ವಧರ್ಮವನ್ನು ನೋಡಿದರೂ ನೀನು ಹಿಂಜರಿಯಬಾರದು, ಏಕೆಂದರೆ ಕ್ಷತ್ರಿಯನಿಗೆ ಧರ್ಮಯುದ್ಧಕ್ಕಿಂತ ಶ್ರೇಷ್ಠವಾದುದು ಬೇರೇನೂ ಇಲ್ಲ.',
32: 'ಹೇ ಪಾರ್ಥ, ತಾನಾಗಿಯೇ ಬಂದ, ತೆರೆದ ಸ್ವರ್ಗದ ಬಾಗಿಲಿನಂತಿರುವ ಇಂಥ ಯುದ್ಧ ಭಾಗ್ಯಶಾಲಿ ಕ್ಷತ್ರಿಯರಿಗೆ ಮಾತ್ರ ಸಿಗುತ್ತದೆ.',
33: 'ಆದರೆ ನೀನು ಈ ಧರ್ಮಯುದ್ಧವನ್ನು ಮಾಡದಿದ್ದರೆ, ನಿನ್ನ ಸ್ವಧರ್ಮವನ್ನೂ ಕೀರ್ತಿಯನ್ನೂ ಕಳೆದುಕೊಂಡು ಪಾಪವನ್ನು ಪಡೆಯುತ್ತೀಯ.',
34: 'ಜನರು ನಿನ್ನ ಅಪಕೀರ್ತಿಯನ್ನು ಸದಾ ಹೇಳುತ್ತಿರುತ್ತಾರೆ. ಗೌರವಾನ್ವಿತನಿಗೆ ಅಪಕೀರ್ತಿ ಸಾವಿಗಿಂತಲೂ ಕೆಟ್ಟದು.',
35: 'ನೀನು ಭಯದಿಂದ ಯುದ್ಧದಿಂದ ಹಿಂದೆ ಸರಿದೆ ಎಂದು ಮಹಾರಥಿಗಳು ಭಾವಿಸುತ್ತಾರೆ. ನಿನ್ನನ್ನು ಬಹಳ ಗೌರವಿಸುತ್ತಿದ್ದವರ ದೃಷ್ಟಿಯಲ್ಲಿ ನೀನು ಕೀಳಾಗುತ್ತೀಯ.',
36: 'ನಿನ್ನ ಶತ್ರುಗಳು ನಿನ್ನ ಸಾಮರ್ಥ್ಯವನ್ನು ನಿಂದಿಸುತ್ತಾ ಹೇಳಬಾರದ ಅನೇಕ ಮಾತುಗಳನ್ನು ಆಡುತ್ತಾರೆ. ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ದುಃಖ ಯಾವುದಿದೆ?',
37: 'ಸತ್ತರೆ ಸ್ವರ್ಗ ಪಡೆಯುತ್ತೀಯ, ಗೆದ್ದರೆ ಭೂಮಿಯನ್ನು ಅನುಭವಿಸುತ್ತೀಯ. ಆದ್ದರಿಂದ ಹೇ ಕೌಂತೇಯ, ಯುದ್ಧಕ್ಕೆ ನಿಶ್ಚಯ ಮಾಡಿ ಎದ್ದೇಳು.',
38: 'ಸುಖ-ದುಃಖ, ಲಾಭ-ನಷ್ಟ, ಜಯ-ಅಪಜಯಗಳನ್ನು ಸಮಾನವೆಂದು ಭಾವಿಸಿ ಯುದ್ಧಕ್ಕೆ ಸಿದ್ಧನಾಗು. ಹೀಗೆ ಮಾಡಿದರೆ ನಿನಗೆ ಪಾಪ ತಟ್ಟುವುದಿಲ್ಲ.',
39: 'ಹೇ ಪಾರ್ಥ, ಇದು ಸಾಂಖ್ಯ (ಜ್ಞಾನ) ದೃಷ್ಟಿಯಿಂದ ನಿನಗೆ ಹೇಳಿದ ಬುದ್ಧಿ. ಈಗ ಯೋಗದ ದೃಷ್ಟಿಯಿಂದ ಇದನ್ನು ಕೇಳು; ಈ ಬುದ್ಧಿಯಿಂದ ಕೂಡಿದರೆ ನೀನು ಕರ್ಮಬಂಧನವನ್ನು ಕಳಚಿಕೊಳ್ಳುತ್ತೀಯ.',
40: 'ಇದರಲ್ಲಿ ಮಾಡಿದ ಪ್ರಯತ್ನ ವ್ಯರ್ಥವಾಗುವುದಿಲ್ಲ, ಯಾವ ಹಾನಿಯೂ ಇಲ್ಲ. ಈ ಧರ್ಮದ ಸ್ವಲ್ಪ ಆಚರಣೆಯೂ ಮಹಾಭಯದಿಂದ ರಕ್ಷಿಸುತ್ತದೆ.',
41: 'ಹೇ ಕುರುನಂದನ, ಇದರಲ್ಲಿ ನಿಶ್ಚಯಾತ್ಮಕ ಬುದ್ಧಿ ಒಂದೇ. ನಿಶ್ಚಯವಿಲ್ಲದವರ ಬುದ್ಧಿ ಅನೇಕ ಶಾಖೆಗಳುಳ್ಳದ್ದು, ಕೊನೆಯಿಲ್ಲದ್ದು.',
42: 'ಹೇ ಪಾರ್ಥ, ವೇದದ ಮಾತುಗಳಲ್ಲಿ ಮುಳುಗಿ "ಇದರಾಚೆ ಬೇರೇನೂ ಇಲ್ಲ" ಎನ್ನುವ ಅವಿವೇಕಿಗಳು ಹೂವಿನಂಥ ಆಕರ್ಷಕ ಮಾತುಗಳನ್ನು ಆಡುತ್ತಾರೆ.',
43: 'ಅವರು ಕಾಮನೆಗಳಿಂದ ತುಂಬಿ, ಸ್ವರ್ಗವನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಭಾವಿಸುತ್ತಾರೆ. ಅವರ ಮಾತುಗಳು ಮರುಜನ್ಮವನ್ನು ಕರ್ಮಫಲವಾಗಿ ನೀಡುವ, ಭೋಗ ಮತ್ತು ಐಶ್ವರ್ಯಕ್ಕಾಗಿ ಅನೇಕ ವಿಧಿಗಳನ್ನು ವರ್ಣಿಸುತ್ತವೆ.',
44: 'ಭೋಗ ಮತ್ತು ಐಶ್ವರ್ಯಗಳಿಗೆ ಅಂಟಿಕೊಂಡು, ಆ ಮಾತುಗಳಿಂದ ಮನಸ್ಸು ಸೆಳೆಯಲ್ಪಟ್ಟವರಲ್ಲಿ ಸಮಾಧಿಯಲ್ಲಿ ನಿಶ್ಚಯಾತ್ಮಕ ಬುದ್ಧಿ ಉಂಟಾಗುವುದಿಲ್ಲ.',
45: 'ವೇದಗಳು ಮೂರು ಗುಣಗಳ ವಿಷಯವನ್ನು ಹೇಳುತ್ತವೆ. ಹೇ ಅರ್ಜುನ, ನೀನು ಮೂರು ಗುಣಗಳಿಗೆ ಅತೀತನಾಗು, ದ್ವಂದ್ವಗಳಿಂದ ಮುಕ್ತನಾಗು, ನಿತ್ಯ ಸತ್ತ್ವದಲ್ಲಿ ನೆಲೆಸು, ಗಳಿಕೆ-ಉಳಿಕೆಯ ಚಿಂತೆ ಬಿಡು, ಆತ್ಮನಿಷ್ಠನಾಗು.',
46: 'ಎಲ್ಲೆಡೆ ನೀರು ತುಂಬಿರುವಾಗ ಸಣ್ಣ ಬಾವಿಯಿಂದ ಎಷ್ಟು ಪ್ರಯೋಜನವೋ, ಬ್ರಹ್ಮವನ್ನು ತಿಳಿದ ಜ್ಞಾನಿಗೆ ಎಲ್ಲ ವೇದಗಳಿಂದಲೂ ಅಷ್ಟೇ ಪ್ರಯೋಜನ.',
49: 'ಹೇ ಧನಂಜಯ, ಬುದ್ಧಿಯೋಗಕ್ಕಿಂತ ಕೇವಲ ಕರ್ಮ ಬಹಳ ಕೀಳು. ಬುದ್ಧಿಯಲ್ಲಿ ಆಶ್ರಯ ಪಡೆ. ಫಲಕ್ಕಾಗಿ ಕರ್ಮ ಮಾಡುವವರು ದೀನರು.',
50: 'ಬುದ್ಧಿಯಿಂದ ಕೂಡಿದವನು ಈ ಲೋಕದಲ್ಲೇ ಪುಣ್ಯ-ಪಾಪ ಎರಡನ್ನೂ ಬಿಟ್ಟುಬಿಡುತ್ತಾನೆ. ಆದ್ದರಿಂದ ಯೋಗದಲ್ಲಿ ತೊಡಗು; ಕರ್ಮದಲ್ಲಿ ಕೌಶಲವೇ ಯೋಗ.',
51: 'ಬುದ್ಧಿಯಿಂದ ಕೂಡಿದ ಜ್ಞಾನಿಗಳು ಕರ್ಮದಿಂದ ಹುಟ್ಟುವ ಫಲವನ್ನು ತ್ಯಜಿಸಿ, ಜನ್ಮಬಂಧನದಿಂದ ಮುಕ್ತರಾಗಿ, ದುಃಖವಿಲ್ಲದ ಸ್ಥಾನವನ್ನು ತಲುಪುತ್ತಾರೆ.',
52: 'ನಿನ್ನ ಬುದ್ಧಿ ಮೋಹದ ಕೆಸರನ್ನು ದಾಟಿದಾಗ, ಕೇಳಿದ್ದರ ಮತ್ತು ಕೇಳಬೇಕಾದ್ದರ ಬಗ್ಗೆ ನಿನಗೆ ವೈರಾಗ್ಯ ಉಂಟಾಗುತ್ತದೆ.',
53: 'ಅನೇಕ ಮಾತುಗಳನ್ನು ಕೇಳಿ ಗೊಂದಲಗೊಂಡ ನಿನ್ನ ಬುದ್ಧಿ ಸಮಾಧಿಯಲ್ಲಿ ಅಚಲವಾಗಿ, ಸ್ಥಿರವಾಗಿ ನಿಂತಾಗ, ನೀನು ಯೋಗವನ್ನು ಪಡೆಯುತ್ತೀಯ.',
54: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಕೇಶವ, ಸಮಾಧಿಯಲ್ಲಿ ನೆಲೆಸಿದ ಸ್ಥಿತಪ್ರಜ್ಞನ ಲಕ್ಷಣ ಏನು? ಸ್ಥಿರ ಬುದ್ಧಿಯವನು ಹೇಗೆ ಮಾತನಾಡುತ್ತಾನೆ, ಹೇಗೆ ಕುಳಿತುಕೊಳ್ಳುತ್ತಾನೆ, ಹೇಗೆ ನಡೆಯುತ್ತಾನೆ?',
55: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಪಾರ್ಥ, ಮನಸ್ಸಿನ ಎಲ್ಲ ಕಾಮನೆಗಳನ್ನು ಬಿಟ್ಟು, ತನ್ನಲ್ಲೇ ತಾನು ತೃಪ್ತನಾಗಿರುವಾಗ, ಅವನನ್ನು ಸ್ಥಿತಪ್ರಜ್ಞ ಎನ್ನುತ್ತಾರೆ.',
56: 'ದುಃಖಗಳಲ್ಲಿ ಮನಸ್ಸು ಕಳವಳಗೊಳ್ಳದ, ಸುಖಗಳಲ್ಲಿ ಆಸೆಯಿಲ್ಲದ, ರಾಗ, ಭಯ ಮತ್ತು ಕ್ರೋಧ ಹೋದ ಮುನಿಯನ್ನು ಸ್ಥಿರಬುದ್ಧಿಯವನು ಎನ್ನುತ್ತಾರೆ.',
57: 'ಎಲ್ಲೆಡೆ ಆಸಕ್ತಿಯಿಲ್ಲದವನು, ಶುಭ ಅಥವಾ ಅಶುಭ ಸಿಕ್ಕಾಗ ಸಂತೋಷಿಸದವನು, ದ್ವೇಷಿಸದವನು: ಅವನ ಬುದ್ಧಿ ಸ್ಥಿರವಾಗಿದೆ.',
58: 'ಆಮೆ ತನ್ನ ಅಂಗಗಳನ್ನು ಎಲ್ಲ ಕಡೆಯಿಂದ ಒಳಗೆ ಎಳೆದುಕೊಳ್ಳುವಂತೆ, ಇಂದ್ರಿಯಗಳನ್ನು ಅವುಗಳ ವಿಷಯಗಳಿಂದ ಹಿಂತೆಗೆದುಕೊಳ್ಳುವವನ ಬುದ್ಧಿ ಸ್ಥಿರವಾಗಿದೆ.',
59: 'ಆಹಾರ ಸೇವಿಸದ ದೇಹಧಾರಿಯಿಂದ ವಿಷಯಗಳು ದೂರವಾಗುತ್ತವೆ, ಆದರೆ ರುಚಿ ಉಳಿಯುತ್ತದೆ. ಪರಮಾತ್ಮನನ್ನು ಕಂಡ ಮೇಲೆ ಅವನ ರುಚಿಯೂ ಹೋಗುತ್ತದೆ.',
60: 'ಹೇ ಕೌಂತೇಯ, ಪ್ರಯತ್ನಿಸುತ್ತಿರುವ ಜ್ಞಾನಿಯ ಮನಸ್ಸನ್ನೂ ಪ್ರಬಲ ಇಂದ್ರಿಯಗಳು ಬಲವಂತವಾಗಿ ಸೆಳೆದುಕೊಂಡು ಹೋಗುತ್ತವೆ.',
61: 'ಅವುಗಳೆಲ್ಲವನ್ನೂ ನಿಗ್ರಹಿಸಿ, ನನ್ನನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಭಾವಿಸಿ, ಯೋಗದಲ್ಲಿ ಕುಳಿತುಕೊಳ್ಳಬೇಕು. ಯಾರ ಇಂದ್ರಿಯಗಳು ವಶದಲ್ಲಿವೆಯೋ ಅವನ ಬುದ್ಧಿ ಸ್ಥಿರವಾಗಿದೆ.',
62: 'ವಿಷಯಗಳನ್ನು ಚಿಂತಿಸುವ ಮನುಷ್ಯನಿಗೆ ಅವುಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಹುಟ್ಟುತ್ತದೆ; ಆಸಕ್ತಿಯಿಂದ ಕಾಮನೆ ಹುಟ್ಟುತ್ತದೆ, ಕಾಮನೆಯಿಂದ ಕ್ರೋಧ ಹುಟ್ಟುತ್ತದೆ.',
63: 'ಕ್ರೋಧದಿಂದ ಮೋಹ, ಮೋಹದಿಂದ ಸ್ಮೃತಿಭ್ರಮೆ, ಸ್ಮೃತಿಭ್ರಮೆಯಿಂದ ಬುದ್ಧಿನಾಶ, ಬುದ್ಧಿನಾಶದಿಂದ ಮನುಷ್ಯ ನಾಶವಾಗುತ್ತಾನೆ.',
64: 'ಆದರೆ ರಾಗ-ದ್ವೇಷಗಳಿಂದ ಮುಕ್ತವಾದ, ತನ್ನ ವಶದಲ್ಲಿರುವ ಇಂದ್ರಿಯಗಳಿಂದ ವಿಷಯಗಳ ನಡುವೆ ಸಂಚರಿಸುವ ಸಂಯಮಿ ಪ್ರಸನ್ನತೆಯನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
65: 'ಪ್ರಸನ್ನತೆಯಲ್ಲಿ ಅವನ ಎಲ್ಲ ದುಃಖಗಳು ನಾಶವಾಗುತ್ತವೆ. ಪ್ರಸನ್ನ ಮನಸ್ಸಿನವನ ಬುದ್ಧಿ ಬೇಗನೆ ಸ್ಥಿರವಾಗುತ್ತದೆ.',
66: 'ಯೋಗದಲ್ಲಿ ತೊಡಗದವನಿಗೆ ಬುದ್ಧಿಯಿಲ್ಲ, ಭಾವನೆಯೂ ಇಲ್ಲ. ಭಾವನೆಯಿಲ್ಲದವನಿಗೆ ಶಾಂತಿಯಿಲ್ಲ; ಶಾಂತಿಯಿಲ್ಲದವನಿಗೆ ಸುಖ ಎಲ್ಲಿಂದ?',
67: 'ಅಲೆದಾಡುವ ಇಂದ್ರಿಯಗಳ ಹಿಂದೆ ಹೋಗುವ ಮನಸ್ಸು, ಗಾಳಿ ನೀರಿನ ಮೇಲಿನ ದೋಣಿಯನ್ನು ಸೆಳೆದೊಯ್ಯುವಂತೆ, ಅವನ ಬುದ್ಧಿಯನ್ನು ಸೆಳೆದೊಯ್ಯುತ್ತದೆ.',
68: 'ಆದ್ದರಿಂದ ಹೇ ಮಹಾಬಾಹು, ಯಾರ ಇಂದ್ರಿಯಗಳು ವಿಷಯಗಳಿಂದ ಸಂಪೂರ್ಣವಾಗಿ ಹಿಂತೆಗೆದುಕೊಂಡಿವೆಯೋ ಅವನ ಬುದ್ಧಿ ಸ್ಥಿರವಾಗಿದೆ.',
69: 'ಎಲ್ಲ ಜೀವಿಗಳಿಗೆ ಯಾವುದು ರಾತ್ರಿಯೋ ಅದರಲ್ಲಿ ಸಂಯಮಿ ಎಚ್ಚರವಾಗಿರುತ್ತಾನೆ. ಜೀವಿಗಳು ಯಾವುದರಲ್ಲಿ ಎಚ್ಚರವಾಗಿರುತ್ತಾರೋ, ಕಾಣುವ ಮುನಿಗೆ ಅದು ರಾತ್ರಿ.',
70: 'ತುಂಬಿದರೂ ಅಚಲವಾಗಿ ನಿಲ್ಲುವ ಸಮುದ್ರಕ್ಕೆ ನದಿಗಳು ಸೇರುವಂತೆ, ಯಾರೊಳಗೆ ಎಲ್ಲ ಕಾಮನೆಗಳು ಸೇರುತ್ತವೆಯೋ ಅವನು ಶಾಂತಿ ಪಡೆಯುತ್ತಾನೆ, ಕಾಮನೆಗಳನ್ನು ಬಯಸುವವನಲ್ಲ.',
71: 'ಎಲ್ಲ ಕಾಮನೆಗಳನ್ನು ಬಿಟ್ಟು, ಆಸೆಯಿಲ್ಲದೆ, "ನನ್ನದು" ಎಂಬ ಭಾವವಿಲ್ಲದೆ, ಅಹಂಕಾರವಿಲ್ಲದೆ ಜೀವಿಸುವವನು ಶಾಂತಿ ಪಡೆಯುತ್ತಾನೆ.',
72: 'ಹೇ ಪಾರ್ಥ, ಇದೇ ಬ್ರಾಹ್ಮೀ ಸ್ಥಿತಿ. ಇದನ್ನು ಪಡೆದವನು ಮೋಹಗೊಳ್ಳುವುದಿಲ್ಲ. ಅಂತ್ಯಕಾಲದಲ್ಲೂ ಇದರಲ್ಲಿ ನೆಲೆಸಿ ಅವನು ಬ್ರಹ್ಮನಿರ್ವಾಣವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
}
